if (n == 0ul) return dcomp{1.0, 0.0};

    // Compute sqrt(n!) using exact factorial for small n, Stirling for large n
    double sqrt_fact;
    if (n < 20ul) {
        double fact = boost::math::factorial<double>(n);
        sqrt_fact = std::sqrt(fact);
    } else {
        double nd = static_cast<double>(n);
        // Stirling approximation: n! ≈ sqrt(2π n) (n/e)^n
        // Hence sqrt(n!) ≈ (2π n)^{1/4} * (n/e)^{n/2}
        const double two_pi = 2.0 * M_PI;
        sqrt_fact = std::pow(two_pi * nd, 0.25) *
                    std::pow(nd / std::exp(1.0), nd * 0.5);
    }

    // alpha^n
    dcomp alpha_pow_n = std::pow(alpha, n);

    return alpha_pow_n / sqrt_fact;
